<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { api, message } from '../api'
import { can, refreshUnread, session } from '../session'
import type { Overview } from '../types'
import Icon from '../components/Icon.vue'
import PageState from '../components/PageState.vue'
const data=ref<Overview>();const loading=ref(true);const error=ref('')
async function load(){loading.value=true;error.value='';try{data.value=await api<Overview>('/overview');void refreshUnread().catch(()=>{})}catch(e){error.value=message(e)}finally{loading.value=false}}
onMounted(load)
const shortcuts=[{path:'/resources',icon:'space',name:'空间资源',text:'查看校园空间，维护基础信息',permission:'spaces.read'}, {path:'/users',icon:'users',name:'账号与权限',text:'管理成员账号与访问范围',permission:'users.manage'},{path:'/notifications',icon:'bell',name:'通知中心',text:'接收与你有关的校园动态',permission:''},{path:'/audit',icon:'audit',name:'操作审计',text:'查阅操作记录，追踪变更来源',permission:'audit.read'}]
</script>
<template><div class="page-heading"><div><div class="eyebrow">WORKSPACE / OVERVIEW</div><h1>你好，{{session.user?.displayName}}<span class="greeting-dot">.</span></h1><p>校园协作，从这里开始。这里是你的公共服务工作台。</p></div><RouterLink to="/resources" class="button secondary">浏览空间<Icon name="arrow" :size="16"/></RouterLink></div><PageState :loading="loading" :error="error" @retry="load"><template v-if="data"><section class="overview-banner"><div><span class="banner-label"><i/> 校园空间 · 有序连接</span><h2>让每一份资源，<br>恰好被需要。</h2><p>统一维护空间信息，为预约、审批与报修提供共同起点。</p><RouterLink to="/resources" class="banner-link">探索资源目录<Icon name="arrow" :size="17"/></RouterLink></div><div class="banner-graphic" aria-hidden="true"><div class="orbit o1"/><div class="orbit o2"/><div class="graphic-block gb1"/><div class="graphic-block gb2"/><div class="graphic-block gb3"/><span class="graphic-label">CAMPUS / CONNECTED</span></div></section><section class="stat-grid"><div class="stat-card"><div><span>空间资源总数</span><Icon name="space"/></div><strong>{{data.resources.toLocaleString()}}</strong><small>校区、楼栋、教室与座位</small></div><div class="stat-card"><div><span>教室</span><Icon name="grid"/></div><strong>{{data.rooms.toLocaleString()}}<em>间</em></strong><small>统一编号，清晰归属</small></div><div class="stat-card"><div><span>座位</span><Icon name="chair"/></div><strong>{{data.seats.toLocaleString()}}<em>个</em></strong><small>每一个位置，都有迹可循</small></div><div class="stat-card accent-stat"><div><span>未读通知</span><Icon name="bell"/></div><strong>{{data.unread.toLocaleString()}}<em>条</em></strong><RouterLink to="/notifications">查看我的通知<Icon name="arrow" :size="14"/></RouterLink></div></section><section class="section-space"><div class="section-heading"><h2>常用入口</h2><span>把日常工作，放在顺手的位置</span></div><div class="shortcut-grid"><RouterLink v-for="item in shortcuts.filter(x=>!x.permission||can(x.permission))" :key="item.path" :to="item.path" class="shortcut-card"><span class="shortcut-icon"><Icon :name="item.icon" :size="23"/></span><h3>{{item.name}}</h3><p>{{item.text}}</p><Icon class="shortcut-arrow" name="arrow" :size="17"/></RouterLink></div></section><section class="section-space panel"><div class="panel-heading"><div><h2>教室目录</h2><p>基础信息已集中维护，具体可用时段请以预约结果为准。</p></div><RouterLink to="/resources" class="text-link">全部资源<Icon name="arrow" :size="15"/></RouterLink></div><div v-if="data.recentResources.length" class="room-preview-grid"><RouterLink v-for="room in data.recentResources" :key="room.id" to="/resources" class="room-preview"><span class="room-code">{{room.code}}</span><span class="badge" :class="{neutral:!room.effectiveActive}">{{room.effectiveActive?'基础启用':'已停用'}}</span><h3>{{room.name}}</h3><p><Icon name="users" :size="15"/>容量 {{room.capacity}} 人</p><div class="feature-chips"><span v-for="feature in room.features.slice(0,3)" :key="feature">{{feature}}</span><span v-if="!room.features.length">基础空间</span></div></RouterLink></div><div v-else class="compact-empty"><Icon name="space" :size="30"/><p>还没有教室，先从建立校区和楼栋开始。</p><RouterLink v-if="can('spaces.write')" to="/resources" class="text-link">前往维护空间<Icon name="arrow" :size="15"/></RouterLink></div></section></template></PageState></template>
